package org.sleepwell.app;
import org.junit.Test;import org.json.*;import java.util.*;import static org.junit.Assert.*;
public final class SpeakStorageTest {
 @Test public void explicitTaskMetadataRoundTripsWithoutMicrophoneOrAlarmAuthority()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture();Store store=f.open()){Alarm old=f.load();String raw=old.json().toString();assertEquals(raw,Alarm.read(old.json()).json().toString());Alarm chosen=Alarm.read(old.json());chosen.setRoutine(new ChallengeRoutine(List.of(old.challenges().tasks.get(0),new ChallengeRoutine.Task("Speak",1))));store.save(chosen);JSONObject portable=store.backup();Backup.validate(portable);Backup.restoreData(store,portable);Alarm restored=store.alarm(1);assertFalse(restored.enabled);assertEquals("Speak",restored.challenges().tasks.get(1).type);assertEquals(1,restored.challenges().tasks.get(1).units());assertEquals(chosen.challenges().summary(),new AlarmDefaults(chosen).create(9).challenges().summary());JSONObject invalid=store.backup();invalid.getJSONArray("alarms").getJSONObject(0).getJSONArray("routine").getJSONObject(1).put("rounds",2);String before=BackupFingerprint.read(store);assertThrows(JSONException.class,()->Backup.restoreData(store,invalid));assertEquals(before,BackupFingerprint.read(store));assertTrue(store.rows("SELECT * FROM sound_events").isEmpty());}}
}
